contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        require(address(c).balance >= amount, "insufficient balance for test");
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint afterBalance = address(c).balance;
        assert(
            (reverted && afterBalance == beforeBalance) ||
            (!reverted && afterBalance == beforeBalance - amount)
        );
    }

    receive() external payable {}
}

