// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.assume(address(c).balance >= amount);
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        assertTrue((reverted && afterBalance == beforeBalance) ||
            (!reverted && afterBalance == beforeBalance - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
